package bottlesong

import "strings"

var numberWords = map[int]string{
	0:  "no",
	1:  "one",
	2:  "two",
	3:  "three",
	4:  "four",
	5:  "five",
	6:  "six",
	7:  "seven",
	8:  "eight",
	9:  "nine",
	10: "ten",
}

func Recite(startBottles, takeDown int) []string {
	verses := make([]string, 0, takeDown*5)
	for i := 0; i < takeDown; i++ {
		if i > 0 {
			verses = append(verses, "")
		}
		verses = append(verses, verse(startBottles-i)...)
	}
	return verses
}

func verse(n int) []string {
	name := numberWords[n]
	plural := "bottles"
	if n == 1 {
		plural = "bottle"
	}
	capName := strings.Title(name)
	return []string{
		capName + " green " + plural + " hanging on the wall,",
		capName + " green " + plural + " hanging on the wall,",
		"And if one green bottle should accidentally fall,",
		"There'll be " + numberWords[n-1] + " green " + pluralFor(n-1) + " hanging on the wall.",
	}
}

func pluralFor(n int) string {
	if n == 1 {
		return "bottle"
	}
	return "bottles"
}

